fn average_transfer_rate_correct(segments: &[SegmentMetrics]) -> f64 {
    let total_bytes: f64 = segments.iter().map(|s| s.bytes).sum();
    let total_seconds: f64 = segments.iter().map(|s| s.bytes / s.mb_per_sec).sum();
    total_bytes / total_seconds
}
